## Solution
```csharp[]
public class Solution
{
    public int[] SingleNumber(int[] nums)
    {
        int xor = 0; 
        // xor starts at 0
        // after loop: xor = 1 ^ 2 ^ 1 ^ 3 ^ 5 ^ 2 = 6 (binary 110)

        for (int i = 0; i < nums.Length; i++)
        {
            xor ^= nums[i];
            // step-by-step:
            // xor = 0 ^ 1 = 1
            // xor = 1 ^ 2 = 3
            // xor = 3 ^ 1 = 2
            // xor = 2 ^ 3 = 1
            // xor = 1 ^ 5 = 4
            // xor = 4 ^ 2 = 6
        }

        int bit = xor & -xor;
        // xor = 6 -> 110
        // -xor in binary trick isolates rightmost set bit
        // bit = 010 (decimal 2)
        // meaning: pick a position where the two unique numbers differ

        int a = 0, b = 0;
        // two buckets:
        // a will collect group 1
        // b will collect group 2

        for (int i = 0; i < nums.Length; i++)
        {
            if ((nums[i] & bit) == 0)
            {
                a ^= nums[i];
                // group A:
                // numbers where bit = 0
                // step-by-step:
                // a = 0 ^ 1 = 1
                // a = 1 ^ 2 = 3
                // a = 3 ^ 2 = 1
                // final a = 3
            }
            else
            {
                b ^= nums[i];
                // group B:
                // numbers where bit = 1
                // step-by-step:
                // b = 0 ^ 3 = 3
                // b = 3 ^ 5 = 6
                // b = 6 ^ 5 = 3
                // final b = 5
            }
        }

        if (a > b)
            return new int[] { b, a };
            // ensures ascending order output

        return new int[] { a, b };
        // final output: [3, 5]
    }
}
```

